  const blocked=openProduction.filter(order=>order.plannedConsumption.some(part=>(state.materials.find(material=>material.id===part.materialId)?.stockGrams||0)<part.weightGrams)),overdue=openProduction.filter(order=>Boolean(order.dueDate)&&order.dueDate!<today()).sort((a,b)=>(a.dueDate||"").localeCompare(b.dueDate||"")),nextOrders=openProduction.filter(order=>order.dueDate).sort((a,b)=>(a.dueDate||"").localeCompare(b.dueDate||"")).slice(0,6);
