  const approved=completedProduction.reduce((total,order)=>total+order.approvedQuantity,0),lost=completedProduction.reduce((total,order)=>total+order.lostQuantity,0),successRate=approved+lost?approved/(approved+lost)*100:100,machineHours=completedProduction.reduce((total,order)=>total+order.actualHours,0),financialWarnings=analytics.orders.flatMap(order=>financialBreakdown(order).anomalies.map(message=>({order,message}))),detailContent=dashboardDetail(detail,analytics,state);
