function OrderEditDialog({order,state,open,onOpenChange,save,saving}:{order:any,state:AppState,open:boolean,onOpenChange:(open:boolean)=>void,save:any,saving:boolean}){return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="order-edit-dialog"><DialogHeader><DialogTitle>Editar {order.number}</DialogTitle><DialogDescription>Enquanto estiver em orçamento, valores comerciais e quantidades podem ser corrigidos.</DialogDescription></DialogHeader><form className="order-edit-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const next=updateDraftOrder(state,order.id,{customerName:s(f,"customerName")||"Consumidor",channel:s(f,"channel") as Channel,seller:s(f,"seller"),discount:n(f,"discount"),shippingCharged:n(f,"shippingCharged"),shippingPaid:n(f,"shippingPaid"),otherCosts:n(f,"otherCosts"),paymentMethod:s(f,"paymentMethod"),origin:s(f,"origin"),campaignId:s(f,"campaignId")||undefined,note:s(f,"note"),items:order.items.map((item:any)=>({id:item.id,quantity:n(f,`quantity-${item.id}`),unitPrice:n(f,`price-${item.id}`),discount:n(f,`item-discount-${item.id}`)}))});if(await save(next,"order-edit")){toast.success("Orçamento atualizado");onOpenChange(false)}}catch(err:any){toast.error(err.message)}}}><div className="form-grid cols-3"><Field label="Cliente" name="customerName" value={order.customerName} required/><SelectField label="Canal" name="channel" value={order.channel}>{Object.entries(channelLabel).map(([value,label])=><option value={value} key={value}>{label}</option>)}</SelectField><Field label="Vendedor" name="seller" value={order.seller}/><Field label="Desconto geral" name="discount" type="number" step=".01" value={order.discount}/><Field label="Frete cobrado" name="shippingCharged" type="number" step=".01" value={order.shippingCharged}/><Field label="Frete pago" name="shippingPaid" type="number" step=".01" value={order.shippingPaid}/><Field label="Outros custos" name="otherCosts" type="number" step=".01" value={order.otherCosts}/><Field label="Forma de pagamento" name="paymentMethod" value={order.paymentMethod}/><Field label="Origem" name="origin" value={order.origin}/><SelectField label="Campanha" name="campaignId" value={order.campaignId||""}><option value="">Nenhuma</option>{state.campaigns.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</SelectField><Field label="Observação" name="note" value={order.note} className="span-2"/></div><div className="section-label"><span>Itens</span><small>Produtos não podem ser substituídos após a criação.</small></div><div className="order-edit-items">{order.items.map((item:any)=><div key={item.id}><span><b>{item.productName}</b><small>{item.productSku}</small></span><Field label="Quantidade" name={`quantity-${item.id}`} type="number" value={item.quantity} required/><Field label="Preço unitário" name={`price-${item.id}`} type="number" step=".01" value={item.unitPrice} required/><Field label="Desconto" name={`item-discount-${item.id}`} type="number" step=".01" value={item.discount}/></div>)}</div><DialogFooter><Button type="button" variant="outline" onClick={()=>onOpenChange(false)}>Cancelar</Button><SaveButton saving={saving}>Salvar orçamento</SaveButton></DialogFooter></form></DialogContent></Dialog>}
function OrderActions({order,state,save,saving}:{order:any,state:AppState,save:any,saving:boolean}){
  const allowed=orderTransitions[order.status]||[],[lossWarning,setLossWarning]=useState<{profit:number;margin:number}|null>(null);
  if(!allowed.length)return <span className="muted">Fluxo encerrado</span>;
  return <details className="inline-details"><summary>Próxima ação</summary><form className="popover-form" onSubmit={async e=>{
    e.preventDefault();
    const f=new FormData(e.currentTarget),status=s(f,"status") as any;
    try{
      let next;
      if(status==="concluido"){
        next=completeSale(state,order.id,n(f,"ads"));
        const result=financialBreakdown(next.orders.find((item:any)=>item.id===order.id));
        if(result.calculatedProfit<0&&!f.get("confirmLoss")){
          setLossWarning({profit:result.calculatedProfit,margin:result.margin});
          toast.error("Revise e confirme a venda com prejuízo antes de concluir.");
          return;
        }
      }else if(status==="devolvido")next=returnSale(state,order.id);else next=transitionOrder(state,order.id,status);
      if(await save(next,"order-status")){
        setLossWarning(null);
        const resulting=next.orders.find((item:any)=>item.id===order.id),message=status==="concluido"?"Venda concluída":status==="devolvido"?"Devolução registrada":status==="aprovado"&&resulting?.status==="pronto"?"Pedido aprovado e estoque separado":status==="aprovado"&&resulting?.status==="producao"?"Pedido aprovado e produção planejada":"Pedido atualizado";
        toast.success(message);
      }
    }catch(err:any){toast.error(err.message)}
  }}><SelectField label="Próxima etapa" name="status" value={allowed[0]}>{allowed.map(x=><option key={x} value={x}>{statusLabel(x)}</option>)}</SelectField>{allowed.includes("concluido")&&<Field label="Custo de anúncios desta venda" name="ads" type="number" step=".01" value={order.advertisingCost||0}/>} {lossWarning&&<div className="sale-loss-warning"><AlertTriangle/><div><b>Esta venda gera prejuízo de {money(Math.abs(lossWarning.profit))}</b><small>Margem estimada: {lossWarning.margin.toFixed(1)}%. Confira custos, frete e anúncios.</small><label><input type="checkbox" name="confirmLoss" required/> Confirmo que desejo concluir esta venda com prejuízo.</label></div></div>}<SaveButton saving={saving}>{lossWarning?"Confirmar prejuízo e concluir":"Confirmar ação"}</SaveButton></form></details>
}

function FinancePage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const month=today().slice(0,7),sales=state.orders.filter(o=>o.status==="concluido"&&(o.completedAt||o.createdAt).startsWith(month)),received=state.payments.filter(p=>p.status==="pago"&&p.receivedAt?.startsWith(month)).reduce((a,p)=>a+p.received,0),receivable=state.payments.filter(p=>p.status!=="pago"&&p.status!=="estornado").reduce((a,p)=>a+Math.max(0,p.expected-p.received),0),paidExpenses=state.expenses.filter(e=>e.status==="pago"&&e.paidAt?.startsWith(month)).reduce((a,e)=>a+e.amount,0),salesProfit=sales.reduce((a,o)=>a+o.profit,0),cash=received-paidExpenses;
  return <><PageHead title="Financeiro" description="Recebimentos, despesas e resultado real do caixa."/><div className="stats-grid"><Stat label="Recebido no mês" value={money(received)} tone="green"/><Stat label="A receber" value={money(receivable)}/><Stat label="Despesas pagas" value={money(paidExpenses)} tone="red"/><Stat label="Saldo de caixa" value={money(cash)} detail={`Lucro operacional ${money(salesProfit)}`} tone={cash>=0?"green":"red"}/></div><div className="dashboard-grid"><Section title="Nova despesa"><form className="form-grid cols-2" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),expense={id:uid(),description:s(f,"description"),category:s(f,"category")||"Geral",amount:n(f,"amount"),dueDate:s(f,"dueDate")||today(),recurring:Boolean(f.get("recurring")),status:"pendente" as const,note:s(f,"note"),createdAt:new Date().toISOString()};if(await save({...state,expenses:[...state.expenses,expense]},"expense-create")){toast.success("Despesa registrada");e.currentTarget.reset()}}}><Field label="Descrição" name="description" required/><Field label="Categoria" name="category"/><Field label="Valor" name="amount" type="number" step=".01" required/><Field label="Vencimento" name="dueDate" type="date" value={today()}/><Field label="Observação" name="note"/><label className="check-field"><input type="checkbox" name="recurring"/>Despesa recorrente</label><SaveButton saving={saving}>Registrar despesa</SaveButton></form></Section><Section title="Contas a receber"><div className="simple-list">{state.payments.filter(p=>p.status!=="estornado").slice().reverse().slice(0,20).map(p=>{const order=state.orders.find(o=>o.id===p.orderId);return <div key={p.id}><span><b>{order?.number||"Pedido"}</b><small>{order?.customerName} · vence {dateLabel(p.dueDate)}</small></span><span><b>{money(p.expected-p.received)}</b>{p.status!=="pago"&&<Button size="sm" variant="outline" onClick={async()=>{const receivedAt=new Date().toISOString(),next={...state,payments:state.payments.map(x=>x.id===p.id?{...x,received:x.expected,receivedAt,status:"pago" as const}:x),orders:state.orders.map(o=>o.id===p.orderId?{...o,paymentStatus:"pago" as const}:o)};if(await save(next,"payment-received"))toast.success("Recebimento confirmado")}}>Receber</Button>}</span></div>})}</div></Section></div><Section title="Despesas"><DataTable headers={["Descrição","Categoria","Vencimento","Valor","Situação","Ação"]}>{state.expenses.slice().reverse().map(e=><tr key={e.id}><td><b>{e.description}</b><small>{e.note}</small></td><td>{e.category}</td><td>{dateLabel(e.dueDate)}</td><td>{money(e.amount)}</td><td><Badge variant={e.status==="pago"?"secondary":"outline"}>{statusLabel(e.status)}</Badge></td><td>{e.status==="pendente"&&<Button size="sm" variant="outline" onClick={async()=>{const paidAt=new Date().toISOString();if(await save({...state,expenses:state.expenses.map(x=>x.id===e.id?{...x,status:"pago" as const,paidAt}:x)},"expense-paid"))toast.success("Despesa paga")}}>Marcar paga</Button>}</td></tr>)}</DataTable></Section></>
}

function MarketingPage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const sales=state.orders.filter(o=>o.status==="concluido"),ads=sales.reduce((a,o)=>a+o.advertisingCost,0),attributed=sales.filter(o=>o.campaignId).reduce((a,o)=>a+o.netRevenue,0),newCustomerIds=new Set<string>();let newCount=0;sales.slice().sort((a,b)=>a.createdAt.localeCompare(b.createdAt)).forEach(o=>{if(o.customerId&&!newCustomerIds.has(o.customerId)){newCustomerIds.add(o.customerId);newCount++}});
  return <><PageHead title="Marketing" description="Campanhas, mídia atribuída, CAC e retorno sobre anúncios."/><div className="stats-grid compact"><Stat label="Mídia atribuída" value={money(ads)}/><Stat label="CAC médio" value={money(newCount?ads/newCount:0)}/><Stat label="ROAS atribuído" value={(ads?attributed/ads:0).toFixed(2)+"x"}/></div><Section title="Nova campanha"><form className="form-grid cols-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),campaign={id:uid(),name:s(f,"name"),platform:s(f,"platform"),startDate:s(f,"startDate"),endDate:s(f,"endDate"),investment:n(f,"investment"),objective:s(f,"objective"),target:s(f,"target"),note:s(f,"note"),status:"active" as const};if(await save({...state,campaigns:[...state.campaigns,campaign]},"campaign-create")){toast.success("Campanha cadastrada");e.currentTarget.reset()}}}><Field label="Nome" name="name" required/><Field label="Plataforma" name="platform" required/><Field label="Início" name="startDate" type="date" value={today()}/><Field label="Fim" name="endDate" type="date"/><Field label="Investimento" name="investment" type="number" step=".01"/><Field label="Objetivo" name="objective"/><Field label="Produto ou público" name="target"/><Field label="Observação" name="note"/><SaveButton saving={saving}>Cadastrar campanha</SaveButton></form></Section><div className="campaign-grid">{state.campaigns.map(c=>{const orders=sales.filter(o=>o.campaignId===c.id),revenue=orders.reduce((a,o)=>a+o.netRevenue,0),allocated=orders.reduce((a,o)=>a+o.advertisingCost,0);return <Card key={c.id}><CardContent><div className="campaign-head"><div><small>{c.platform}</small><b>{c.name}</b></div><Badge>{statusLabel(c.status)}</Badge></div><div className="price-grid"><div><span>Investimento</span><b>{money(c.investment)}</b></div><div><span>Atribuído</span><b>{money(allocated)}</b></div><div><span>Receita</span><b>{money(revenue)}</b></div><div><span>ROAS</span><b>{(allocated?revenue/allocated:0).toFixed(2)}x</b></div></div><Progress value={c.investment?Math.min(100,allocated/c.investment*100):0}/><small>{money(Math.max(0,c.investment-allocated))} ainda não atribuído</small></CardContent></Card>})}</div></>
}

function ReportsPage({state}:{state:AppState}){
  const[period,setPeriod]=useState("all"),sales=state.orders.filter(o=>o.status==="concluido"&&(period==="all"||(o.completedAt||o.createdAt).startsWith(period))),expenses=state.expenses.filter(e=>e.status==="pago"&&(period==="all"||(e.paidAt||e.dueDate).startsWith(period))),items=sales.flatMap(o=>o.items),byProduct=new Map<string,{name:string,qty:number,revenue:number,profit:number}>();items.forEach(i=>{const x=byProduct.get(i.productId)||{name:i.productName,qty:0,revenue:0,profit:0};x.qty+=i.quantity;x.revenue+=i.revenue;x.profit+=i.profit;byProduct.set(i.productId,x)});const months=[...new Set([...state.orders.map(o=>o.createdAt.slice(0,7)),...state.expenses.map(e=>e.dueDate.slice(0,7))])].sort().reverse(),revenueTotal=sales.reduce((a,o)=>a+o.netRevenue,0),operationalProfit=sales.reduce((a,o)=>a+o.profit,0),expenseTotal=expenses.reduce((a,e)=>a+e.amount,0),netProfit=operationalProfit-expenseTotal,netMargin=revenueTotal?netProfit/revenueTotal*100:0;
  function csv(){const lines=[["Produto","Quantidade","Receita","Lucro","Margem"],...[...byProduct.values()].map(x=>[x.name,x.qty,x.revenue,x.profit,x.revenue?x.profit/x.revenue*100:0])];const blob=new Blob([lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(";")).join("\n")],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="relatorio-operacional.csv";a.click();URL.revokeObjectURL(a.href)}
  return <><PageHead title="Relatórios" description="Resultado realizado, produção, estoque e rentabilidade." action={<div className="actions"><select value={period} onChange={e=>setPeriod(e.target.value)}><option value="all">Todo o período</option>{months.map(m=><option key={m} value={m}>{m}</option>)}</select><Button variant="outline" onClick={csv}><Download/>Exportar CSV</Button></div>}/><div className="stats-grid"><Stat label="Receita líquida" value={money(revenueTotal)}/><Stat label="Lucro operacional" value={money(operationalProfit)} tone="green"/><Stat label="Despesas" value={money(expenseTotal)} tone="red"/><Stat label="Resultado líquido" value={money(netProfit)} detail={`${netMargin.toFixed(1)}% de margem`} tone={netProfit>=0?"green":"red"}/></div><Section title="Rentabilidade por produto">{byProduct.size?<DataTable headers={["Produto","Vendidas","Receita","Lucro","Margem"]}>{[...byProduct.values()].sort((a,b)=>b.profit-a.profit).map(x=><tr key={x.name}><td><b>{x.name}</b></td><td>{x.qty}</td><td>{money(x.revenue)}</td><td className={x.profit>=0?"positive":"negative"}>{money(x.profit)}</td><td>{(x.revenue?x.profit/x.revenue*100:0).toFixed(1)}%</td></tr>)}</DataTable>:<Empty title="Sem dados no período" description="Conclua vendas para gerar os indicadores."/>}</Section></>
}

function MachinesPage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const[createOpen,setCreateOpen]=useState(false);
  return <><PageHead title="Máquinas" description="Capacidade, depreciação, horas e manutenção das impressoras." action={<Button onClick={()=>setCreateOpen(true)}><Plus/>Nova máquina</Button>}/><div className="machine-grid">{state.machines.map(m=>{const usage=m.lifeHours?m.accumulatedHours/m.lifeHours*100:0,maintenance=state.maintenances.filter(x=>x.machineId===m.id);return <Card key={m.id}><CardContent><div className="machine-head"><div className="machine-icon"><Printer/></div><div><b>{m.name}</b><small>{m.model||"Modelo não informado"}</small></div><Badge>{statusLabel(m.status)}</Badge></div><div className="machine-stats"><span>{m.accumulatedHours.toFixed(1)} h utilizadas</span><span>{usage.toFixed(1)}% da vida útil</span></div><Progress value={Math.min(100,usage)}/><div className="product-footer"><span>Depreciação <b>{money(m.lifeHours?m.acquisitionValue/m.lifeHours:0)}/h</b></span><span>Manutenções <b>{maintenance.length}</b></span></div><details className="inline-details"><summary>Registrar manutenção</summary><form className="popover-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),maintenance={id:uid(),machineId:m.id,kind:s(f,"kind") as any,cost:n(f,"cost"),date:s(f,"date")||today(),machineHours:m.accumulatedHours,note:s(f,"note")};if(await save({...state,maintenances:[...state.maintenances,maintenance],machines:state.machines.map(x=>x.id===m.id?{...x,lastMaintenance:maintenance.date}:x)},"maintenance-create"))toast.success("Manutenção registrada")}}><SelectField label="Tipo" name="kind"><option value="preventiva">Preventiva</option><option value="corretiva">Corretiva</option></SelectField><Field label="Custo" name="cost" type="number" step=".01"/><Field label="Data" name="date" type="date" value={today()}/><Field label="Observação" name="note"/><SaveButton saving={saving}>Registrar</SaveButton></form></details></CardContent></Card>})}</div>{!state.machines.length&&<Empty title="Nenhuma máquina cadastrada" description="Cadastre a primeira impressora para planejar e acompanhar a produção."/>}<Dialog open={createOpen} onOpenChange={setCreateOpen}><DialogContent className="entity-dialog"><DialogHeader><DialogTitle>Nova máquina</DialogTitle><DialogDescription>Cadastre os dados usados no planejamento e no custo real das produções.</DialogDescription></DialogHeader><form className="dialog-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),machine={id:uid(),name:s(f,"name"),model:s(f,"model"),acquisitionValue:n(f,"value"),lifeHours:n(f,"life"),powerKw:n(f,"power"),accumulatedHours:n(f,"hours"),status:"active" as const};if(await save({...state,machines:[...state.machines,machine]},"machine-create")){toast.success("Máquina cadastrada");setCreateOpen(false)}}}><div className="form-grid cols-2"><Field label="Identificação" name="name" required/><Field label="Modelo" name="model"/><Field label="Valor de aquisição" name="value" type="number" step=".01"/><Field label="Vida útil (h)" name="life" type="number"/><Field label="Potência (kW)" name="power" type="number" step=".001"/><Field label="Horas atuais" name="hours" type="number" step=".1"/></div><DialogFooter><Button type="button" variant="outline" onClick={()=>setCreateOpen(false)}>Cancelar</Button><SaveButton saving={saving}>Cadastrar máquina</SaveButton></DialogFooter></form></DialogContent></Dialog></>
}

function SettingsPage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const labels={energyRate:"Tarifa de energia (R$/kWh)",power:"Potência padrão (kW)",manualHourRate:"Valor da hora manual",machineValue:"Valor padrão da máquina",machineLife:"Vida útil padrão (h)",markup:"Markup (%)",taxRate:"Impostos (%)",packagingCost:"Embalagem por unidade",maintenancePercent:"Reserva de manutenção (%)",minPrice:"Preço mínimo",rounding:"Arredondamento",shopeeFee:"Taxa Shopee (%)",shopeeFixed:"Taxa fixa Shopee",mlFee:"Taxa Mercado Livre (%)",mlFixed:"Taxa fixa Mercado Livre"};
  return <><PageHead title="Parâmetros" description="Valores usados apenas em novos cálculos e fichas técnicas."/><Section title="Custos e canais"><form className="form-grid cols-3" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),settings=Object.fromEntries(Object.keys(defaults).map(k=>[k,n(f,k)])) as any;if(await save({...state,settings},"settings-update"))toast.success("Parâmetros atualizados")}}>{Object.keys(defaults).map(k=><Field key={k} label={labels[k]} name={k} type="number" step=".01" value={state.settings[k]}/>) }<SaveButton saving={saving}>Salvar parâmetros</SaveButton></form></Section><Section title="Fornecedores"><form className="form-grid cols-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),supplier={id:uid(),name:s(f,"name"),contact:s(f,"contact"),email:s(f,"email"),note:s(f,"note"),status:"active" as const};if(await save({...state,suppliers:[...state.suppliers,supplier]},"supplier-create")){toast.success("Fornecedor cadastrado");e.currentTarget.reset()}}}><Field label="Nome" name="name" required/><Field label="Contato" name="contact"/><Field label="E-mail" name="email"/><Field label="Observação" name="note"/><SaveButton saving={saving}>Cadastrar fornecedor</SaveButton></form><div className="simple-list">{state.suppliers.map(x=><div key={x.id}><b>{x.name}</b><span>{x.contact||x.email||"Sem contato"}</span></div>)}</div></Section><Section title="Metas mensais"><form className="form-grid cols-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),goal={id:uid(),month:s(f,"month"),revenue:n(f,"revenue"),profit:n(f,"profit"),margin:n(f,"margin"),production:n(f,"production"),sales:n(f,"sales"),cac:n(f,"cac"),roas:n(f,"roas")};if(await save({...state,goals:[...state.goals.filter(g=>g.month!==goal.month),goal]},"goal-save"))toast.success("Meta salva")}}><Field label="Mês" name="month" type="month" required/><Field label="Faturamento" name="revenue" type="number" step=".01"/><Field label="Lucro" name="profit" type="number" step=".01"/><Field label="Margem (%)" name="margin" type="number" step=".1"/><Field label="Produção" name="production" type="number"/><Field label="Vendas" name="sales" type="number"/><Field label="CAC" name="cac" type="number" step=".01"/><Field label="ROAS" name="roas" type="number" step=".01"/><SaveButton saving={saving}>Salvar meta</SaveButton></form></Section><div className="backup-actions"><Button variant="outline" onClick={()=>{const a=document.createElement("a"),u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"}));a.href=u;a.download="backup-gestao-3d.json";a.click();URL.revokeObjectURL(u)}}><Download/>Exportar backup</Button><label className="upload-button"><Upload/>Importar backup<Input type="file" accept=".json" onChange={async e=>{try{const raw=JSON.parse(await e.target.files![0].text()),next=raw.materials?hydrateState(raw):migrateLegacy(raw);if(await save(next,"backup-import"))toast.success("Backup importado")}catch{toast.error("Arquivo inválido")}}}/></label></div></>
}
